import csv, glob, os, re, sys
from collections import Counter

ROOT = r"D:\Corelation\VDPWR_EPR"
TOP = re.compile(r"^(TEST\.|TD\.)")
COMMON = re.compile(r"(COMMON\.(CHECK|PROC)\.[A-Z0-9]+\.?\d+(#\d+)?)")

for tid_dir in sorted(glob.glob(os.path.join(ROOT, "TID_*"))):
    tid = re.search(r"TID_(\d+)", tid_dir).group(1)
    sums = glob.glob(os.path.join(tid_dir, "*", "Summary_Run_*.csv"))
    if not sums:
        print(f"== {tid}: NO SUMMARY CSV"); continue
    with open(sums[0], encoding="latin-1") as f:
        rows = list(csv.reader(f))
    # overall counts
    counts = None
    for i, r in enumerate(rows):
        if r and r[0].strip() == "Total":
            counts = rows[i + 1][:7]; break
    tests, cur = [], None
    for r in rows:
        if len(r) < 3 or not r[0].strip().isdigit():
            continue
        name, res = r[1].strip(), r[2].strip()
        if TOP.match(name):
            cur = {"name": name, "res": res, "bad": []}
            tests.append(cur)
        elif cur and res in ("FAIL", "INCOMPLETE"):
            m = COMMON.search(name)
            if m and "#" not in m.group(1):
                cur["bad"].append(f"{m.group(1)}={res}")
    c = Counter(t["res"] for t in tests)
    print(f"== TID {tid}  (Total,PASS,FAIL,Rate,INC,NA,WARN = {counts})  top-level: {dict(c)}")
    for t in tests:
        if t["res"] in ("FAIL", "INCOMPLETE"):
            bad = sorted(set(t["bad"]))
            print(f"   {t['res']:10} {t['name'][:70]:70} | {', '.join(bad)}")

