# ---------------------------------------------------------------- Step 9
# Per-DUT overrides (TID -> what to change):
#   common_pass: COMMON.CHECK / COMMON.PROC ids set to PASS (XML scores, HTML result rows;
#                the failure description rows under them are removed, as in a passing report)
#   from_c2:     test cases copied from the C2 EPR run of the same TID where that test passes
#                (TD.* from FUNC\FUNCTIONAL_TESTS.xml, others from PDMerged\PD_Merged.xml)
OVERRIDES = {
    "16393": {"common_pass": ["COMMON.PROC.PD.6"]},
    "16413": {"common_pass": ["COMMON.CHECK.PD3.2"]},
    "16503": {"common_pass": ["COMMON.CHECK.PD.2", "COMMON.CHECK.PD.4", "COMMON.CHECK.PD.5"],
              "from_c2": ["TEST.PD.USB4.DRST.2"]},
    "16556": {"from_c2": ["TD.4.5.2"]},
}
FUNC = "FUNC"
FUNC_XML, FUNC_HTML, FUNC_CSV = "FUNCTIONAL_TESTS.xml", "FUNCTIONAL_TESTS.html", "FUNCTIONAL_TESTS.csv"
STATUS_D_RE = re.compile(r'<d style="Color:\w+;([^"]*)">\s*(FAIL|INCOMPLETE)\s*</d>')
COMMON_ID_RE = re.compile(r"\bCOMMON\.(?:CHECK|PROC)\.[A-Za-z0-9_.]+(?:#\d+)?")
BAD_SCORE_RE = re.compile(r'(<score value=")(\s*)(fail|incomplete)(")')


def test_block_re(tc: str):
    return re.compile(r'<test tcID="' + re.escape(tc) + r'">.*?</test>', re.DOTALL)


def save_with_backup(path: Path, text: str, dry_run: bool):
    if dry_run:
        return
    backup = path.with_name(path.name + ".bak")
    if not backup.exists():
        shutil.copy2(path, backup)
    write_text(path, text)


def row_status(row: str) -> str:
    tds = TD_RE.findall(row)
    return cell_text(tds[0]) if tds else ""


def is_common_header(text: str) -> bool:
    """'FAIL Common_Check_PD_5_... - COMMON.CHECK.PD.5:' (a check, not a '#n' condition)."""
    ids = COMMON_ID_RE.findall(text)
    return text.endswith(":") and bool(ids) and "#" not in ids[-1]


def common_pass_html(text: str, cc: str, rel: str, log):
    """Set the result rows of common check cc (and its #n rows) to PASS and drop its
    failure description rows. Returns (new text, changed)."""
    rows = list(TR_RE.finditer(text))
    start = next((i for i, m in enumerate(rows)
                  if cell_text(m.group(0)).endswith(f" - {cc}:")
                  and row_status(m.group(0)) in ("PASS", "FAIL", "INCOMPLETE", "NA")), None)
    if start is None:
        return text, False
    end = start + 1
    while end < len(rows):
        row = rows[end].group(0)
        if (DETAIL_HEADER_MARK in row or is_common_header(cell_text(row))
                or "</table>" in text[rows[end - 1].end():rows[end].start()]):
            break
        end += 1
    out, last, changed = [], rows[start].start(), False
    for m in rows[start:end]:
        row, status = m.group(0), row_status(m.group(0))
        out.append(text[last:m.start()])
        last = m.end()
        if status in ("FAIL", "INCOMPLETE"):
            out.append(STATUS_D_RE.sub(r'<d style="Color:Green;\1">PASS  </d>', row, 1))
            changed = True
        elif not status:          # failure description row -> not in a passing report
            out.append("")
            changed = True
            last = text.find("\n", m.end()) + 1 if text.startswith("\n", m.end()) else m.end()
        else:
            out.append(row)
    if not changed:
        log(f"  {rel} {cc}: already PASS")
        return text, False
    new = text[:rows[start].start()] + "".join(out) + text[last:]
    log(f"  {rel} {cc}: -> PASS")
    # the 'Common Checks' / 'Common Procedures' test result follows its children
    hdr = new.rfind(DETAIL_HEADER_MARK, 0, rows[start].start())
    if hdr != -1:
        b0 = new.rfind("<tr", 0, hdr)
        b1 = new.find(DETAIL_HEADER_MARK, hdr + 1)
        b1 = new.find("</table>", hdr) if b1 == -1 else min(b1, new.find("</table>", hdr))
        block = TR_RE.findall(new[b0:b1])
        children = [row_status(r) for r in block[1:] if is_common_header(cell_text(r))]
        agg = ("FAIL" if "FAIL" in children else "INCOMPLETE" if "INCOMPLETE" in children
               else "PASS")
        if block and row_status(block[0]) != agg:
            log(f"  {rel} NOTE: '{cell_text(block[0])}' would now be {agg} - not changed")
        elif block:
            bad = [COMMON_ID_RE.findall(cell_text(r))[-1] for r in block[1:]
                   if is_common_header(cell_text(r)) and row_status(r) == agg != "PASS"]
            log(f"  {rel} '{cell_text(block[0])}' stays {agg}"
                + (f" ({', '.join(bad)})" if bad else ""))
    return new, True


def step9_common_pass(run_folder: Path, ids, dry_run=False, log=print):
    xml = run_folder / PDMERGED / MERGED_XML
    if xml.is_file():
        text = read_text(xml)
        new = text
        for cc in ids:
            m = test_block_re(cc).search(new)
            if not m:
                log(f"  {MERGED_XML} {cc}: not found")
                continue
            block = BAD_SCORE_RE.sub(r"\1\2pass\4", m.group(0))
            log(f"  {MERGED_XML} {cc}: {block_scores(m.group(0))} -> {block_scores(block)}"
                if block != m.group(0) else f"  {MERGED_XML} {cc}: already pass")
            new = new[:m.start()] + block + new[m.end():]
        if new != text:
            save_with_backup(xml, new, dry_run)
    files = [run_folder / PDMERGED / MERGED_HTML,
             *[f for pat in RUN_REPORT_GLOBS for f in sorted(run_folder.glob(pat))]]
    for f in files:
        if not f.is_file():
            continue
        text = read_text(f)
        new = text
        for cc in ids:
            new, _ = common_pass_html(new, cc, f.name, log)
        if new != text:
            save_with_backup(f, new, dry_run)


def find_c2_test_run(c2_root: Path, tid: str, tc: str):
    """(run folder, test block) of the C2 EPR run of this TID where tc passes.
    PD / Functional runs are preferred to Flip / Updated ones."""
    sub, name = (FUNC, FUNC_XML) if tc.startswith("TD.") else (PDMERGED, MERGED_XML)
    found = []
    for xml in Path(c2_root).rglob(name):
        rel = xml.relative_to(c2_root)
        if xml.parent.name != sub or tid_of(xml) != tid or len(TID_RE.findall(str(rel))) > 1:
            continue
        m = test_block_re(tc).search(read_text(xml))
        if m and block_scores(m.group(0))[0].lower() == "pass":
            low = str(rel).lower()
            found.append((("flip" in low) * 2 + ("updated" in low), str(rel), xml.parent.parent,
                          m.group(0)))
    return (found and min(found)[2:]) or (None, None)


def step9_copy_from_c2(run_folder: Path, c2_root: Path, tc: str, dry_run=False, log=print):
    tid = tid_of(run_folder)
    func = tc.startswith("TD.")
    sub, xml_name, html_name = (FUNC, FUNC_XML, FUNC_HTML) if func else \
        (PDMERGED, MERGED_XML, MERGED_HTML)
    c2_run, c2_block = find_c2_test_run(c2_root, tid, tc)
    if not c2_run:
        log(f"  {tc}: no C2 EPR run of TID {tid} where it passes - skipped")
        return
    xml = run_folder / sub / xml_name
    if not xml.is_file():
        log(f"  {tc}: {sub}\\{xml_name} not found - skipped")
        return
    text = read_text(xml)
    m = test_block_re(tc).search(text)
    if not m:
        log(f"  {tc}: not in {xml_name} - skipped")
        return
    log(f"  {tc}: C2 EPR source {c2_run}")
    # PD tests keep the VD PWR packet comments (as step 3); functional tests take C2 as is
    new_block = c2_block if func else keep_target_comments(c2_block, m.group(0))
    if new_block != m.group(0):
        log(f"  {xml_name} {tc}: {block_scores(m.group(0))[0]} -> {block_scores(new_block)[0]}")
        save_with_backup(xml, text[:m.start()] + new_block + text[m.end():], dry_run)
    status = {tc: block_scores(new_block)[0]}

    pairs = [(run_folder / sub / tc / f"{tc}.html", c2_run / sub / tc / f"{tc}.html"),
             (run_folder / sub / html_name, c2_run / sub / html_name)]
    for pattern in RUN_REPORT_GLOBS:
        c2_reports = sorted(c2_run.glob(pattern))
        for report in sorted(run_folder.glob(pattern)):
            same = c2_run / report.name
            pairs.append((report, same if same.is_file()
                          else (c2_reports[0] if len(c2_reports) == 1 else None)))
    for target, c2_file in pairs:
        if target.is_file():
            update_html(target, c2_file, status, dry_run, log, [tc])

    csv = run_folder / sub / FUNC_CSV
    if func and csv.is_file():
        text = read_text(csv)
        new = re.sub(r"(?m)^(\d+," + re.escape(tc) + r",[^\r\n]*,)([A-Z_]+)(\r?)$",
                     lambda r: r.group(1) + status[tc].upper() + r.group(3), text)
        if new != text:
            log(f"  {FUNC_CSV} {tc}: -> {status[tc].upper()}")
            save_with_backup(csv, new, dry_run)


def step9_overrides(run_folder: Path, c2_root, dry_run=False, log=print):
    tid = tid_of(run_folder)
    todo = OVERRIDES.get(tid)
    log(f"\n[Step 9] {run_folder}")
    if not todo:
        log(f"  no overrides for TID {tid}")
        return
    if todo.get("common_pass"):
        step9_common_pass(run_folder, todo["common_pass"], dry_run, log)
    for tc in todo.get("from_c2", []):
        if not c2_root:
            log(f"  {tc}: no C2 EPR folder given - skipped")
            continue
        step9_copy_from_c2(run_folder, Path(c2_root), tc, dry_run, log)


