def is_common_header(text: str) -> bool:
    """'FAIL Common_Check_PD_5_... - COMMON.CHECK.PD.5:' (a check, not a '#n' condition)."""
    ids = COMMON_ID_RE.findall(text)
    return text.endswith(":") and bool(ids) and "#" not in ids[-1]


def common_pass_html(text: str, cc: str, rel: str, log):
    """Set the result rows of common check cc (and its #n rows) to PASS and drop its
    failure description rows. Returns (new text, changed)."""
    rows = list(TR_RE.finditer(text))
    start = next((i for i, m in enumerate(rows)
                  if cell_text(m.group(0)).endswith(f" - {cc}:")
                  and row_status(m.group(0)) in ("PASS", "FAIL", "INCOMPLETE", "NA")), None)
    if start is None:
        return text, False
    end = start + 1
    while end < len(rows):
        row = rows[end].group(0)
        if (DETAIL_HEADER_MARK in row or is_common_header(cell_text(row))
                or "</table>" in text[rows[end - 1].end():rows[end].start()]):
            break
        end += 1
    out, last, changed = [], rows[start].start(), False
    for m in rows[start:end]:
        row, status = m.group(0), row_status(m.group(0))
        out.append(text[last:m.start()])
        last = m.end()
        if status in ("FAIL", "INCOMPLETE"):
            out.append(STATUS_D_RE.sub(r'<d style="Color:Green;\1">PASS  </d>', row, 1))
            changed = True
        elif not status:          # failure description row -> not in a passing report
            out.append("")
            changed = True
            last = text.find("\n", m.end()) + 1 if text.startswith("\n", m.end()) else m.end()
        else:
            out.append(row)
    if not changed:
        log(f"  {rel} {cc}: already PASS")
        return text, False
    new = text[:rows[start].start()] + "".join(out) + text[last:]
    log(f"  {rel} {cc}: -> PASS")
    # the 'Common Checks' / 'Common Procedures' test result follows its children
    hdr = new.rfind(DETAIL_HEADER_MARK, 0, rows[start].start())
    if hdr != -1:
        b0 = new.rfind("<tr", 0, hdr)
        b1 = new.find(DETAIL_HEADER_MARK, hdr + 1)
        b1 = new.find("</table>", hdr) if b1 == -1 else min(b1, new.find("</table>", hdr))
        block = TR_RE.findall(new[b0:b1])
        children = [row_status(r) for r in block[1:] if is_common_header(cell_text(r))]
        agg = ("FAIL" if "FAIL" in children else "INCOMPLETE" if "INCOMPLETE" in children
               else "PASS")
        if block and row_status(block[0]) != agg:
            log(f"  {rel} NOTE: '{cell_text(block[0])}' would now be {agg} - not changed")
        elif block:
            bad = [COMMON_ID_RE.findall(cell_text(r))[-1] for r in block[1:]
                   if is_common_header(cell_text(r)) and row_status(r) == agg != "PASS"]
            log(f"  {rel} '{cell_text(block[0])}' stays {agg}"
                + (f" ({', '.join(bad)})" if bad else ""))
    return new, True


def step9_common_pass(run_folder: Path, ids, dry_run=False, log=print):
    xml = run_folder / PDMERGED / MERGED_XML
