    # actual statuses of result summary rows
    act=Counter()
    for m in c.TR_RE.finditer(t):
        r=m.group(0)
        if "<a href=#PKT" in r or re.search(r"<b>(TEST\.|TD\.|\d+\.\d+</b>)",r):
