    out=[]
    x=run/"FUNC/FUNCTIONAL_TESTS.xml"
    if x.is_file():
        m=re.search(r'<test tcID="'+re.escape(tc)+r'">.*?</test>',c.read_text(x),re.S)
        out.append("xml="+(c.SCORE_RE.findall(m.group(0))[0] if m else "absent"))
