    for f in [run/"FUNC/FUNCTIONAL_TESTS.html",*run.glob("GRL_USB_PD_Report_*.html"),*run.glob("Summary_Run_*.html")]:
        t=c.read_text(f); r=next((m.group(0) for m in c.TR_RE.finditer(t) if "<a href=#PKT" in m.group(0) and re.search(r"(^|\s)"+re.escape(tc)+r"(\s|$)",c.cell_text(m.group(0)))),None)
        d=c.find_detail_block(t,tc)
