    return " ".join(out)
for spec in sys.argv[1:]:
    root,tcs=spec.split("=")
    for run in sorted(Path(".").glob(root)):
        if not (run/"FUNC").is_dir(): continue
        print("##",run)
        for tc in tcs.split(","): print(f"  {tc:10} {st(run,tc)}")
