"""Manual edit: put selected tests back to the original VDPWR_EPR result in Output."""
import re, shutil
import corelation as c
from pathlib import Path
SRC, OUT = Path("VDPWR_EPR"), Path("Output/VDPWR_EPR")
P = "TEST.PD."
ITEMS = {
    "16393": [P+"PROT.SRC.9"],
    "16556": [P+"PROT.SRC.9", P+"USB4.DRST.1", P+"PS.SRC.5"],
    "16557": [P+"PROT.SRC.9", P+"USB4.DRST.1", P+"PS.SRC.5"],
    "16502": ["COMMON.CHECK.PD.15"],
    "16503": [P+"USB4.DRST.1"],
}
def html_key(tc):  # HTML name of the item
    return "Common Checks" if tc.startswith("COMMON.") else tc
def has(text, key):
    return re.search(r"(^|\s)" + re.escape(key) + r"(\s|$)", text) is not None
def summary_row(t, key):
    for m in c.TR_RE.finditer(t):
        if "<a href=#PKT" in m.group(0) and has(c.cell_text(m.group(0)), key):
            return m
def detail(t, key):
    for m in c.TR_RE.finditer(t):
        r = m.group(0)
        if c.DETAIL_HEADER_MARK in r and has(c.cell_text(r), key):
            end = t.find("</table>", m.end()); nxt = t.find(c.DETAIL_HEADER_MARK, m.end(), end)
            if nxt != -1: end = t.rfind("<tr", m.end(), nxt)
            return m.start(), end
def status(row): return c.cell_text(c.TD_RE.findall(row)[-1])
def xml_block(t, tc):
    return re.search(r'<test tcID="' + re.escape(tc) + r'">.*?</test>', t, re.S)

for tid, tcs in ITEMS.items():
    for o in sorted(OUT.glob(f"TID_{tid}*/*/")):
        s = SRC / o.relative_to(OUT)
        print(f"\n## {tid} {o.name}")
        # XML
        x = o/"PDMerged/PD_Merged.xml"; t = c.read_text(x); so = c.read_text(s/"PDMerged/PD_Merged.xml")
        for tc in tcs:
            a, b = xml_block(t, tc), xml_block(so, tc)
            if a and b and a.group(0) != b.group(0):
                t = t[:a.start()] + b.group(0) + t[a.end():]
                print(f"  XML {tc}: {c.SCORE_RE.findall(a.group(0))[0]} -> {c.SCORE_RE.findall(b.group(0))[0]}")
        c.write_text(x, t)
        # HTML reports
        for f in [o/"PDMerged/PD_Merged.html", *o.glob("GRL_USB_PD_Report_*.html"), *o.glob("Summary_Run_*.html")]:
            t, so = c.read_text(f), c.read_text(s/f.relative_to(o)); moves = []
            for key in dict.fromkeys(html_key(tc) for tc in tcs):
                d, sd = detail(t, key), detail(so, key)
                if d and sd and t[d[0]:d[1]] != so[sd[0]:sd[1]]:
                    t = t[:d[0]] + so[sd[0]:sd[1]] + t[d[1]:]
                r, sr = summary_row(t, key), summary_row(so, key)
                if r and sr and r.group(0) != sr.group(0):
                    old, new = status(r.group(0)), status(sr.group(0))
                    t = t[:r.start()] + sr.group(0) + t[r.end():]
                    if old != new: moves.append((c.moi_of(t, r.start()), old, new))
                    print(f"  {f.name} {key}: {old} -> {new}")
            if moves: t = c.adjust_counts(t, moves, lambda m: print("  ", m))
            c.write_text(f, t)
        # per-test HTML
        for tc in tcs:
            p = o/"PDMerged"/tc/f"{tc}.html"; sp = s/"PDMerged"/tc/f"{tc}.html"
            if p.is_file() and sp.is_file() and c.read_text(p) != c.read_text(sp):
                shutil.copy2(sp, p); print(f"  {p.name}: copied from original")
